}
```
(add `import Box from "@mui/material/Box";` if not already present -- check the current imports first).
6. Replace the empty-return at line 106 with a targeted empty state, also wrapped in the same `GamesHorizontalList` (this component already imports `useAuth` for `isSignedIn`, line 33):
```tsx
if (mySeries.length === 0 && joinableSeries.length === 0) {
  return (
    <GamesHorizontalList title="קבוצות פעילות">
      <Box p={2} width="100%">
        <Typography variant="body2" color="text.secondary">
          {isSignedIn ? "אין עדיין קבוצות פעילות" : "התחבר כדי לשחק עם חברים בקבוצה קבועה"}
        </Typography>
